export function copyDefaultOptions(mainOptions, elementOptions, fields) {
  let field;
  for (let idx = 0; idx < fields.length; idx++) {
    field = fields[idx];
    if (elementOptions && !defined(elementOptions[field])) {
      elementOptions[field] = mainOptions[field];
    }
  }
}
