export const events = [ZOOM_END, ZOOM_START, PAN, SELECT, ITEMROTATE, ITEMBOUNDSCHANGE, CHANGE, CLICK, MOUSE_ENTER, MOUSE_LEAVE, TOOLTIP_SHOW, TOOLTIP_HIDE, 'toolBarClick', 'save', 'cancel', 'edit', 'remove', 'undo', 'redo', 'add', 'dataBound', ...domEvents, DRAG_START, DRAG, DRAG_END];
export function splitDiagramElements(elements) {
  const connections = [];
  const shapes = [];
  let element, idx;
  for (idx = 0; idx < elements.length; idx++) {
    element = elements[idx];
    if (element instanceof Shape) {
      shapes.push(element);
    } else {
      connections.push(element);
    }
  }
  return {
    shapes: shapes,
    connections: connections
  };
}
export function preventDefault(e) {
  e.preventDefault();
}
export function elementOffset(element) {
  const rect = element.getBoundingClientRect();
  const doc = element.ownerDocument;
  const scrollLeft = doc.defaultView.scrollX || doc.documentElement.scrollLeft || 0;
  const scrollTop = doc.defaultView.scrollY || doc.documentElement.scrollTop || 0;
  return {
    top: rect.top + scrollTop,
    left: rect.left + scrollLeft
  };
}
export function outerWidth(element, includeMargins = false) {
  let widthValue = element.offsetWidth; // Width of the element with padding and border
  if (includeMargins) {
    const style = getComputedStyle(element);
    const marginLeft = parseFloat(style.marginLeft);
    const marginRight = parseFloat(style.marginRight);
    widthValue += marginLeft + marginRight;
  }
  return widthValue;
}
export function outerHeight(element, includeMargins = false) {
  let heightValue = element.offsetHeight;
  if (includeMargins) {
    const style = getComputedStyle(element);
    const marginTop = parseFloat(style.marginTop);
    const marginBottom = parseFloat(style.marginBottom);
    heightValue += marginTop + marginBottom;
  }
  return heightValue;
}
export function elementWidth(element) {
  const style = getComputedStyle(element);
  const widthValue = element.clientWidth; // Includes content + padding
  const paddingLeft = parseFloat(style.paddingLeft);
  const paddingRight = parseFloat(style.paddingRight);
  return widthValue - paddingLeft - paddingRight; // Only content
}
export function elementHeight(element) {
  const style = getComputedStyle(element);
  const heightValue = element.clientHeight;
  const paddingTop = parseFloat(style.paddingTop);
  const paddingBottom = parseFloat(style.paddingBottom);
  return heightValue - paddingTop - paddingBottom;
}