import { getTemplate } from '../services/template/get-template';
import { Cursors, INLINE, NEW_LINE_CHAR, WRAP } from './../constants';
import { randomId } from './../math';
import { Group, MultiLineTextBlock, TextBlock, RichTextBlock, textRect, getFont } from './../svg';
import { isString, isUndefined } from './../utils';
